class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def reverseList(head: ListNode) -> ListNode:
    prev = None
    cur = head
    while cur:
        nxt = cur.next      # 1) 暂存后继
        cur.next = prev     # 2) 反向
        prev = cur          # 3) 推进
        cur = nxt
    return prev

import random

def findKthLargest(nums, k: int) -> int:
    target = len(nums) - k  # 第 k 大 = 升序下标 n-k

    def quickselect(lo, hi):
        pivot = nums[random.randint(lo, hi)]
        i, j = lo, hi
        while i <= j:
            while nums[i] < pivot:
                i += 1
            while nums[j] > pivot:
                j -= 1
            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
        if target <= j:
            return quickselect(lo, j)
        if target >= i:
            return quickselect(i, hi)
        return nums[target]

    return quickselect(0, len(nums) - 1)

