import heapq

def findKthLargest(nums, k: int) -> int:
    heap = []
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)  # 只保留最大的 k 个
    return heap[0]  # 堆顶即第 k 大

