def threeSum(nums):
    nums.sort()
    res = set()
    for i in range(len(nums) - 2):
        if nums[i] > 0:
            break
        seen = set()                    # 处理 i 时记录出现过的数
        target = -nums[i]
        for j in range(i + 1, len(nums)):
            if target - nums[j] in seen:
                res.add((nums[i], target - nums[j], nums[j]))
            seen.add(nums[j])
    return [list(t) for t in res]
